from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute, extendedMarketHours=False).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Securities[self.option_symbol].SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.Securities[self.option_symbol].SetFilter(
            lambda universe: universe.Strikes(-200, 200).Expiration(0, 365)
        )

        self.closes = deque(maxlen=20)
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()

        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            if not self.IsOrderOpen(self.exit_ticket):
                self.ClearOptionState()
            return

        today = self.Time.date()

        # Emergency expiration handling: do not intentionally retain an expiring option.
        if today >= self.held_expiry:
            self.no_entry_date = today
            if not self.IsOrderOpen(self.exit_ticket):
                self.Debug(f"Expiration exit for {self.held_contract}")
                self.SubmitExit("expiration")
            return

        if self.IsTradingDayBeforeExpiry(today) and self.Time.hour == 15 and self.Time.minute == 45:
            if not self.IsOrderOpen(self.exit_ticket):
                self.Debug(f"Time-stop exit for {self.held_contract}")
                self.SubmitExit("time stop")
            return

        if self.entry_fill_price is None or self.IsOrderOpen(self.exit_ticket):
            return

        quote = self.GetCurrentQuote(slice, self.held_contract)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self.Debug(f"Profit-target exit for {self.held_contract} at midpoint {midpoint:.2f}")
            self.SubmitExit("profit target")

    def OnFiveMinuteBar(self, sender, bar):
        if bar.Symbol != self.spy:
            return

        prior_fast = None
        prior_slow = None
        if len(self.closes) == 20:
            prior_fast = sum(list(self.closes)[-5:]) / 5.0
            prior_slow = sum(self.closes) / 20.0

        self.closes.append(bar.Close)

        if len(self.closes) < 20 or prior_fast is None:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0
        bullish_cross = prior_fast <= prior_slow and current_fast > current_slow

        end_time = bar.EndTime
        eligible_time = (
            (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
            and (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
        )

        if not bullish_cross or not eligible_time:
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None or self.IsOrderOpen(self.entry_ticket):
            return

        self.TryEnterFromCurrentSlice()

    def TryEnterFromCurrentSlice(self):
        slice = self.CurrentSlice
        if slice is None or not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Entry skipped: no SPY option chain in current Slice")
            return

        chain = slice.OptionChains[self.option_symbol]
        current_spy_price = self.Securities[self.spy].Price
        if current_spy_price <= 0:
            self.Debug("Entry skipped: invalid SPY price")
            return

        today = self.Time.date()
        calls = [
            contract for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - today).days > 0
        ]

        if not calls:
            self.Debug("Entry skipped: no eligible future-expiration calls")
            return

        minimum_dte = min((contract.Expiry.date() - today).days for contract in calls)
        expiration_calls = [
            contract for contract in calls
            if (contract.Expiry.date() - today).days == minimum_dte
        ]

        minimum_strike = 1.01 * current_spy_price
        candidates = [
            contract for contract in expiration_calls
            if contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no call satisfies strike rule at selected expiration")
            return

        selected = min(candidates, key=lambda contract: (contract.Strike, str(contract.Symbol)))
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike:.2f}"
        )

    def OnOrderEvent(self, orderEvent):
        if self.entry_ticket is not None and orderEvent.OrderId == self.entry_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.held_contract = orderEvent.Symbol
                self.held_expiry = orderEvent.Symbol.ID.Date.date()
                self.entry_fill_price = orderEvent.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}"
                )

            elif orderEvent.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Entry order closed without fill: {orderEvent.Symbol}")

        if self.exit_ticket is not None and orderEvent.OrderId == self.exit_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {orderEvent.Symbol} at {orderEvent.FillPrice:.2f}")
                self.ClearOptionState()

            elif orderEvent.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Exit order closed without fill: {orderEvent.Symbol}")

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        if self.IsOrderOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing existing exit order")

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity > 0:
            self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
            self.Debug(f"Exit submitted ({reason}): {self.held_contract}")

    def GetCurrentQuote(self, slice, symbol):
        if not slice.QuoteBars.ContainsKey(symbol):
            return None

        quote_bar = slice.QuoteBars[symbol]
        if quote_bar is None or quote_bar.Bid is None or quote_bar.Ask is None:
            return None

        bid = quote_bar.Bid.Close
        ask = quote_bar.Ask.Close
        if bid <= 0 or ask <= 0:
            return None

        return bid, ask

    def IsTradingDayBeforeExpiry(self, date):
        candidate = self.held_expiry - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return date == candidate

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        open_spy_orders = [
            order for order in self.Transactions.GetOpenOrders()
            if order.Symbol == self.spy
        ]
        if not open_spy_orders:
            self.Debug(
                f"Unexpected SPY exercise/assignment position detected ({quantity}); liquidating"
            )
            self.MarketOrder(self.spy, -quantity)

    def IsOrderOpen(self, ticket):
        if ticket is None:
            return False

        return any(
            order.Id == ticket.OrderId
            for order in self.Transactions.GetOpenOrders()
        )

    def ClearOptionState(self):
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None

