from datetime import timedelta
from QuantConnect import (
    DataNormalizationMode,
    OptionRight,
    Resolution,
    TimeZones
)
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Orders import OrderStatus


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-100, 100, 0, 365)
        self.option_symbol = option.Symbol

        self.closes = []
        self.fast_period = 5
        self.slow_period = 20
        self.previous_fast = None
        self.previous_slow = None

        self.held_contract = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.expiration_date = None
        self.blocked_entry_date = None

    def OnData(self, data):
        self._handle_unexpected_spy_position()

        if self.held_contract is not None:
            self._handle_expiration_processing()
            self._handle_time_stop()
            self._handle_profit_target(data)

        self._update_five_minute_signal_and_enter(data)

    def _update_five_minute_signal_and_enter(self, data):
        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None:
            return

        end_time = spy_bar.EndTime
        if not self._is_regular_session_five_minute_close(end_time):
            return

        self.closes.append(float(spy_bar.Close))
        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if not (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45)):
            return
        if end_time.hour > 14 or (end_time.hour == 14 and end_time.minute > 30):
            return

        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_contract is not None or self._has_open_entry_order():
            return

        self._submit_entry_from_current_chain(data)

    def _is_regular_session_five_minute_close(self, time):
        if time.hour < 9 or (time.hour == 9 and time.minute < 35):
            return False
        if time.hour > 16 or (time.hour == 16 and time.minute > 0):
            return False
        return time.minute % 5 == 0

    def _submit_entry_from_current_chain(self, data):
        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped - no SPY option chain.")
            return

        spy_price = float(self.Securities[self.spy].Price)
        if spy_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped - invalid SPY price.")
            return

        today = self.Time.date()
        expirations = sorted(
            {contract.Expiry.date() for contract in chain if contract.Expiry.date() > today}
        )
        if not expirations:
            self.Debug(f"{self.Time}: Entry skipped - no future expiration available.")
            return

        expiration = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped - no call at least 1% OTM for {expiration}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = self.entry_ticket.OrderId
        self.Debug(f"{self.Time}: Submitted entry for {selected.Symbol}.")

    def _handle_profit_target(self, data):
        if self.entry_fill_price is None or self._has_open_exit_order():
            return

        quote = data.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._cancel_open_exit_order()
            quantity = self.Portfolio[self.held_contract].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
                self.exit_order_id = self.exit_ticket.OrderId
                self.Debug(f"{self.Time}: Submitted profit-target exit for {self.held_contract}.")

    def _handle_time_stop(self):
        if self.expiration_date is None or self._has_open_exit_order():
            return

        previous_trading_day = self._previous_trading_day(self.expiration_date)
        if self.Time.date() != previous_trading_day:
            return

        if self.Time.hour == 15 and self.Time.minute == 45:
            self._cancel_open_exit_order()
            quantity = self.Portfolio[self.held_contract].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
                self.exit_order_id = self.exit_ticket.OrderId
                self.Debug(f"{self.Time}: Submitted pre-expiration time-stop exit.")

    def _handle_expiration_processing(self):
        if self.expiration_date is None or self.Time.date() < self.expiration_date:
            return

        self.blocked_entry_date = self.Time.date()
        self._cancel_open_entry_order()
        self._cancel_open_exit_order()

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
            self.exit_order_id = self.exit_ticket.OrderId
            self.Debug(f"{self.Time}: Submitted expiration-protection exit.")

    def _previous_trading_day(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_unexpected_spy_position(self):
        if not self.Portfolio[self.spy].Invested:
            return

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(self.spy, -quantity)
            self.Debug(
                f"{self.Time}: Unexpected SPY exercise/assignment position liquidated."
            )

    def _has_open_entry_order(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (OrderStatus.New, OrderStatus.Submitted)

    def _has_open_exit_order(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (OrderStatus.New, OrderStatus.Submitted)

    def _cancel_open_entry_order(self):
        if self._has_open_entry_order():
            self.entry_ticket.Cancel("Expiration processing")

    def _cancel_open_exit_order(self):
        if self._has_open_exit_order():
            self.exit_ticket.Cancel("Replacing exit order")

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        if order_event.OrderId == self.entry_order_id:
            self.held_contract = order_event.Symbol
            self.entry_fill_price = float(order_event.FillPrice)
            self.expiration_date = order_event.Symbol.ID.Date.date()
            self.entry_ticket = None
            self.entry_order_id = None
            self.Debug(
                f"{self.Time}: Entry filled for {self.held_contract} at "
                f"{self.entry_fill_price:.2f}."
            )
            return

        if order_event.OrderId == self.exit_order_id:
            self.Debug(
                f"{self.Time}: Exit filled for {order_event.Symbol} at "
                f"{float(order_event.FillPrice):.2f}."
            )
            self.held_contract = None
            self.entry_fill_price = None
            self.expiration_date = None
            self.exit_ticket = None
            self.exit_order_id = None

