from AlgorithmImports import *


class FiveMinuteSpyCallCrossover(QCAlgorithm):

    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(-1000, 1000, 0, 730)
        self.option_symbol = option.symbol

        self.fast_closes = RollingWindow[float](5)
        self.slow_closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_fill_price = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.data_consolidated += self.on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy, consolidator)

    def on_data(self, slice):
        if self.portfolio[self.spy].invested:
            quantity = self.portfolio[self.spy].quantity
            if quantity != 0:
                self.debug("Unexpected SPY exercise/assignment position; liquidating.")
                self.market_order(self.spy, -quantity)

        if self.held_contract is not None:
            self.manage_open_option(slice)

    def on_five_minute_bar(self, sender, bar):
        self.fast_closes.add(bar.close)
        self.slow_closes.add(bar.close)

        if not self.slow_closes.is_ready:
            return

        fast = sum(self.fast_closes[i] for i in range(5)) / 5.0
        slow = sum(self.slow_closes[i] for i in range(20)) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        end_time = bar.end_time
        if end_time.hour < 9 or (
            end_time.hour == 9 and end_time.minute < 45
        ):
            return
        if end_time.hour > 14 or (
            end_time.hour == 14 and end_time.minute > 30
        ):
            return

        if self.no_entry_date == self.time.date:
            return

        if self.held_contract is not None or self.portfolio.invested:
            return

        if self.entry_order_is_open():
            return

        self.try_enter_from_current_slice()

    def try_enter_from_current_slice(self):
        slice = self.current_slice
        if slice is None or slice.option_chains is None:
            self.debug("Entry skipped: no option chain.")
            return

        chain = slice.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug("Entry skipped: SPY option chain unavailable.")
            return

        today = self.time.date
        expirations = sorted({
            contract.expiry.date()
            for contract in chain
            if contract.right == OptionRight.CALL
            and (contract.expiry.date() - today).days >= 1
        })

        if not expirations:
            self.debug("Entry skipped: no eligible future call expiration.")
            return

        expiration = expirations[0]
        spot = self.securities[self.spy].price
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() == expiration
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug("Entry skipped: no call meets strike rule.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.strike, str(contract.symbol))
        )[0]

        self.entry_ticket = self.market_order(selected.symbol, 1)
        self.debug(
            f"Entry submitted: {selected.symbol}, strike {selected.strike}, "
            f"expiry {selected.expiry.date()}."
        )

    def manage_open_option(self, slice):
        if not self.portfolio[self.held_contract].invested:
            return

        expiry_date = self.held_contract.id.date.date()
        today = self.time.date

        if today >= expiry_date:
            self.no_entry_date = today
            self.submit_exit("expiration safeguard")
            return

        previous_trading_day = self.get_previous_trading_day(expiry_date)
        if (
            today == previous_trading_day
            and self.time.hour == 15
            and self.time.minute == 45
        ):
            self.submit_exit("pre-expiration time stop")
            return

        contract = self.get_contract_from_slice(slice, self.held_contract)
        if contract is None:
            return

        bid = contract.bid_price
        ask = contract.ask_price
        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if (
            self.entry_fill_price is not None
            and midpoint >= self.entry_fill_price * 1.50
        ):
            self.submit_exit("50% profit target")

    def get_contract_from_slice(self, slice, symbol):
        if slice.option_chains is None:
            return None

        for chain in slice.option_chains.values():
            for contract in chain:
                if contract.symbol == symbol:
                    return contract
        return None

    def get_previous_trading_day(self, date):
        return self.securities[self.spy].exchange.hours.get_previous_trading_day(date)

    def entry_order_is_open(self):
        if self.entry_ticket is None:
            return False

        status = self.entry_ticket.status
        return status in [
            OrderStatus.NEW,
            OrderStatus.SUBMITTED,
            OrderStatus.PARTIALLY_FILLED
        ]

    def exit_order_is_open(self):
        if self.exit_ticket is None:
            return False

        status = self.exit_ticket.status
        return status in [
            OrderStatus.NEW,
            OrderStatus.SUBMITTED,
            OrderStatus.PARTIALLY_FILLED
        ]

    def submit_exit(self, reason):
        if self.held_contract is None or not self.portfolio[self.held_contract].invested:
            return

        if self.exit_order_is_open():
            return

        if self.exit_ticket is not None:
            self.exit_ticket.cancel("Replacing prior exit order.")

        quantity = self.portfolio[self.held_contract].quantity
        if quantity == 0:
            return

        self.exit_ticket = self.market_order(self.held_contract, -quantity)
        self.debug(f"Exit submitted: {reason}, {self.held_contract}.")

    def on_order_event(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.order_id == self.entry_ticket.order_id
            and order_event.status == OrderStatus.FILLED
        ):
            self.held_contract = order_event.symbol
            self.entry_fill_price = order_event.fill_price
            self.entry_ticket = None
            self.debug(
                f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}."
            )

        if (
            self.exit_ticket is not None
            and order_event.order_id == self.exit_ticket.order_id
            and order_event.status == OrderStatus.FILLED
        ):
            self.debug(f"Exit filled: {order_event.symbol} at {order_event.fill_price:.2f}.")
            self.held_contract = None
            self.entry_fill_price = None
            self.exit_ticket = None

        if (
            self.entry_ticket is not None
            and order_event.order_id == self.entry_ticket.order_id
            and order_event.status in [OrderStatus.CANCELED, OrderStatus.INVALID]
        ):
            self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.order_id == self.exit_ticket.order_id
            and order_event.status in [OrderStatus.CANCELED, OrderStatus.INVALID]
        ):
            self.exit_ticket = None

    def on_assignment_order_event(self, assignment_event):
        self.debug("Unexpected option assignment detected; liquidating any SPY position.")
        if self.portfolio[self.spy].invested:
            self.market_order(self.spy, -self.portfolio[self.spy].quantity)

