from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(
            lambda universe: universe.include_weeklys()
            .strikes(-1000, 1000)
            .expiration(0, 365)
        )
        self.option_symbol = option.symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_price = None
        self.entry_blocked_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.data_consolidated += self._on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy, consolidator)

    def _on_five_minute_bar(self, sender, bar):
        prior_fast = self.fast.current.value if self.fast.is_ready else None
        prior_slow = self.slow.current.value if self.slow.is_ready else None

        self.fast.update(bar.end_time, bar.close)
        self.slow.update(bar.end_time, bar.close)

        if prior_fast is None or prior_slow is None:
            return

        if not self.fast.is_ready or not self.slow.is_ready:
            return

        bullish_cross = (
            prior_fast <= prior_slow and
            self.fast.current.value > self.slow.current.value
        )

        end = bar.end_time
        eligible_time = (
            (end.hour == 9 and end.minute >= 45) or
            (end.hour > 9 and end.hour < 14) or
            (end.hour == 14 and end.minute <= 30)
        )

        if bullish_cross and eligible_time:
            self.pending_entry = True

    def on_data(self, data):
        if self.entry_blocked_date != self.time.date():
            self.entry_blocked_date = None

        if self.portfolio[self.spy].invested:
            self.debug(
                f"{self.time}: Unexpected SPY exercise/assignment position; liquidating."
            )
            self.liquidate(self.spy)

        if self.held_contract is not None:
            expiration = self.held_contract.id.date.date()

            if self.time.date() >= expiration:
                self.entry_blocked_date = self.time.date()
                self._submit_exit("expiration processing")
            else:
                self._check_profit_target(data)
                self._check_time_stop(expiration)

        if self.pending_entry:
            self.pending_entry = False
            self._try_enter(data)

    def _try_enter(self, data):
        if self.entry_blocked_date == self.time.date():
            return

        if self.held_contract is not None or self.portfolio.invested:
            return

        if self._ticket_is_open(self.entry_ticket):
            return

        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug(f"{self.time}: Entry skipped: no SPY option chain.")
            return

        spot = self.securities[self.spy].price
        if spot <= 0:
            self.debug(f"{self.time}: Entry skipped: unavailable SPY price.")
            return

        today = self.time.date()
        expirations = sorted({
            contract.expiry.date()
            for contract in chain
            if contract.right == OptionRight.CALL
            and (contract.expiry.date() - today).days > 0
        })

        if not expirations:
            self.debug(f"{self.time}: Entry skipped: no valid future call expiration.")
            return

        expiration = expirations[0]
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() == expiration
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug(
                f"{self.time}: Entry skipped: no call at least 1% OTM for {expiration}."
            )
            return

        selected = min(candidates, key=lambda c: (c.strike, str(c.symbol)))
        self.entry_ticket = self.market_order(selected.symbol, 1)
        self.debug(
            f"{self.time}: Entry submitted for {selected.symbol} "
            f"(strike {selected.strike}, expiry {expiration})."
        )

    def _check_profit_target(self, data):
        if self.entry_price is None or self.entry_price <= 0:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (item for item in chain if item.symbol == self.held_contract),
            None
        )
        if contract is None or contract.bid_price <= 0 or contract.ask_price <= 0:
            return

        midpoint = (contract.bid_price + contract.ask_price) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self._submit_exit("50% profit target")

    def _check_time_stop(self, expiration):
        if self.time.hour != 15 or self.time.minute != 45:
            return

        exchange_hours = self.securities[self.spy].exchange.hours
        expiry_datetime = datetime.combine(expiration, datetime.min.time())
        previous_trading_day = exchange_hours.get_previous_trading_day(expiry_datetime)

        if self.time.date() == previous_trading_day.date():
            self._submit_exit("15:45 pre-expiration time stop")

    def _submit_exit(self, reason):
        if self.held_contract is None or self._ticket_is_open(self.exit_ticket):
            return

        quantity = self.portfolio[self.held_contract].quantity
        if quantity == 0:
            return

        self.transactions.cancel_open_orders(self.held_contract)
        self.exit_ticket = self.market_order(self.held_contract, -quantity)
        self.debug(f"{self.time}: Exit submitted for {self.held_contract}: {reason}.")

    def on_order_event(self, order_event):
        if self.entry_ticket is not None and order_event.order_id == self.entry_ticket.order_id:
            if order_event.fill_quantity > 0 and order_event.fill_price > 0:
                self.held_contract = order_event.symbol
                self.entry_price = order_event.fill_price
                self.debug(
                    f"{self.time}: Entry filled for {order_event.symbol} "
                    f"at {order_event.fill_price}."
                )

            if order_event.status in [OrderStatus.CANCELED, OrderStatus.INVALID]:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.order_id == self.exit_ticket.order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(f"{self.time}: Exit filled for {order_event.symbol}.")
                self.held_contract = None
                self.entry_price = None
                self.exit_ticket = None

    def _ticket_is_open(self, ticket):
        return ticket is not None and ticket.status not in [
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID
        ]

