                self.debug(f"Entry order did not complete: {self.held_contract}")
                if self.portfolio[self.held_contract].quantity == 0:
                    self.held_contract = None
                    self.entry_fill_price = None

        if self.exit_ticket is not None and order_event.order_id == self.exit_ticket.order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(f"Exit filled: {self.held_contract}, price={order_event.fill_price:.2f}")

            if (
                order_event.status in [OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID]
                and self.held_contract is not None
                and self.portfolio[self.held_contract].quantity == 0
            ):
                self.held_contract = None
                self.entry_fill_price = None
                self.entry_ticket = None
                self.exit_ticket = None

    def entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.status not in [
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ]
        )

    def exit_order_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.status not in [
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ]
        )

    def previous_trading_day(self, expiration_date):
        return self.securities[self.spy].exchange.hours.get_previous_trading_day(
