from AlgorithmImports import *
from datetime import timedelta


class FiveMinuteSpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-100, 100, timedelta(0), timedelta(days=90))
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.held_contract = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.spy_cleanup_order_id = None
        self.no_entry_dates = set()

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy_symbol, consolidator)

    def OnData(self, slice):
        self.HandleUnexpectedSpyHolding()
        self.HandleExpirationProtection()
        self.HandlePositionExit(slice)

    def OnFiveMinuteBar(self, bar):
        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value
        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross:
            return

        end_time = bar.EndTime
        if end_time.time() < time(9, 45) or end_time.time() > time(14, 30):
            return

        if end_time.date() in self.no_entry_dates:
            return

        if self.HasOptionHolding() or self.entry_order_id is not None:
            return

        self.TryEnter(bar.Close)

    def TryEnter(self, spy_price):
        slice = self.CurrentSlice
        if slice is None or not slice.OptionChains:
            self.Debug("Entry skipped: no option chain in current Slice.")
            return

        chain = None
        for candidate in slice.OptionChains.Values:
            if candidate.Underlying.Symbol == self.spy_symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Entry skipped: SPY option chain unavailable.")
            return

        today = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts
            if contract.Right == OptionRight.Call and
            (contract.Expiry.date() - today).days > 0
        })

        if not expirations:
            self.Debug("Entry skipped: no future call expiration available.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain.Contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call strike.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        contract = candidates[0]

        ticket = self.MarketOrder(contract.Symbol, 1, tag="Bullish five-minute MA crossover")
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {contract.Symbol}, expiry {selected_expiry}, "
            f"DTE {(selected_expiry - today).days}."
        )

    def HandlePositionExit(self, slice):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        if self.exit_order_id is not None:
            return

        expiry_date = self.held_contract.ID.Date.date()
        previous_trading_day = self.OptionPreviousTradingDay(expiry_date)

        if self.Time.date() == previous_trading_day and self.Time.hour == 15 and self.Time.minute == 45:
            self.SubmitExit("Expiration time stop")
            return

        quote = slice.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        if self.entry_price is not None and midpoint >= self.entry_price * 1.50:
            self.SubmitExit("50% profit target")

