from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            True,
            0,
            False,
            DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-100, 100, 0, 365)
        self.option_symbol = option.Symbol

        self.five_minute_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bar_slots = {}
        self.last_finalized_slot = None

        self.held_option = None
        self.held_expiry = None
        self.entry_price = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.spy_flatten_pending = False
        self.no_entry_date = None

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()

        if self.held_option is not None and self.Time.date() >= self.held_expiry:
            self.no_entry_date = self.Time.date()
            self._submit_exit("expiration processing")
            return

        self._update_five_minute_bars(data)

        if self.held_option is not None:
            self._check_exit_conditions(data)

    def _update_five_minute_bars(self, data: Slice):
        spy_bar = data.Bars.get(self.spy)

        if spy_bar is not None:
            end_time = spy_bar.EndTime
            slot_end = self._five_minute_slot_end(end_time)

            if self._is_regular_session_slot(slot_end):
                if slot_end not in self.bar_slots:
                    self.bar_slots[slot_end] = {}

                self.bar_slots[slot_end][end_time] = spy_bar.Close

        ready_slots = sorted(
            slot for slot in self.bar_slots
            if slot <= self.Time and
            (self.last_finalized_slot is None or slot > self.last_finalized_slot)
        )

        for slot_end in ready_slots:
            minute_bars = self.bar_slots.pop(slot_end)

            expected_times = [
                slot_end - timedelta(minutes=i)
                for i in range(1, 6)
            ]

            self.last_finalized_slot = slot_end

            if not all(t in minute_bars for t in expected_times):
                continue

            self._on_completed_five_minute_bar(slot_end, minute_bars[slot_end])

    def _five_minute_slot_end(self, bar_end_time):
        remainder = bar_end_time.minute % 5
        if remainder == 0 and bar_end_time.second == 0:
            return bar_end_time

        return bar_end_time + timedelta(
            minutes=5 - remainder,
            seconds=-bar_end_time.second,
            microseconds=-bar_end_time.microsecond
        )

    def _is_regular_session_slot(self, slot_end):
        current_time = slot_end.time()
        return current_time >= datetime.strptime("09:35", "%H:%M").time() and \
               current_time <= datetime.strptime("16:00", "%H:%M").time()

    def _on_completed_five_minute_bar(self, bar_end, close):
        self.five_minute_closes.append(close)

        if len(self.five_minute_closes) < 20:
            return

        closes = list(self.five_minute_closes)
        fast = sum(closes[-5:]) / 5.0
        slow = sum(closes[-20:]) / 20.0

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        bar_time = bar_end.time()
        if bar_time < datetime.strptime("09:45", "%H:%M").time() or \
           bar_time > datetime.strptime("14:30", "%H:%M").time():
            return

        self._try_enter_call()

    def _try_enter_call(self):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None or self._ticket_is_open(self.entry_ticket):
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        if self.Portfolio[self.spy].Quantity != 0:
            return

        chain = self.CurrentSlice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: entry skipped; no SPY option chain.")
            return

        contracts = list(chain.Contracts.Values)
        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if (contract.Expiry.date() - self.Time.date()).days > 0
        })

        if not valid_expiries:
            self.Debug(f"{self.Time}: entry skipped; no valid future expiration.")
            return

        expiry = valid_expiries[0]
        target_strike = self.Securities[self.spy].Price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= target_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: entry skipped; no qualifying call for {expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"{self.Time}: submitted call entry for {selected.Symbol}, "
            f"expiry {expiry}, strike {selected.Strike}."
        )

    def _check_exit_conditions(self, data: Slice):
        if self.held_option is None or self.Portfolio[self.held_option].Quantity == 0:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        if self.Time.hour == 15 and self.Time.minute == 45:
            if self._is_day_before_expiration(self.Time.date(), self.held_expiry):
                self._submit_exit("15:45 pre-expiration time stop")
                return

        contract = self._get_held_contract(data)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self._submit_exit("50% profit target")

    def _get_held_contract(self, data: Slice):
        for chain in data.OptionChains.Values:
            contract = chain.Contracts.get(self.held_option)
            if contract is not None:
                return contract
        return None

    def _is_day_before_expiration(self, current_date, expiry_date):
        next_date = current_date + timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime.combine(next_date, datetime.min.time())
        ):
            next_date += timedelta(days=1)

        return next_date == expiry_date

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0 or self._ticket_is_open(self.exit_ticket):
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order.")

        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug(
            f"{self.Time}: submitted exit for {self.held_option}; reason: {reason}."
        )

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            self.spy_flatten_pending = False
            return

        if self.spy_flatten_pending:
            return

        self.spy_flatten_pending = True
        self.MarketOrder(self.spy, -quantity)
        self.Debug(
            f"{self.Time}: unexpected SPY exercise/assignment position; "
            f"submitted liquidation for {quantity} shares."
        )

    def _ticket_is_open(self, ticket):
        if ticket is None:
            return False

        status = ticket.Status
        return status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted,
            OrderStatus.CancelPending
        ]

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and \
           order_event.OrderId == self.entry_ticket.OrderId:

            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_option = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date.date()
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None

                self.Debug(
                    f"{self.Time}: entry filled for {self.held_option} "
                    f"at {self.entry_price}."
                )

            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_ticket = None
                self.Debug(f"{self.Time}: entry order was not filled.")

        if self.exit_ticket is not None and \
           order_event.OrderId == self.exit_ticket.OrderId:

            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: exit filled for {order_event.Symbol} "
                    f"at {order_event.FillPrice}."
                )
                self.held_option = None
                self.held_expiry = None
                self.entry_price = None
                self.exit_ticket = None

            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

