            contract.Expiry.date()
            for contract in contracts
            if (contract.Expiry.date() - self.Time.date()).days > 0
        })

        if not valid_expiries:
            self.Debug(f"{self.Time}: entry skipped; no valid future expiration.")
            return

        expiry = valid_expiries[0]
        target_strike = self.Securities[self.spy].Price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= target_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: entry skipped; no qualifying call for {expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"{self.Time}: submitted call entry for {selected.Symbol}, "
            f"expiry {expiry}, strike {selected.Strike}."
        )

    def _check_exit_conditions(self, data: Slice):
        if self.held_option is None or self.Portfolio[self.held_option].Quantity == 0:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        if self.Time.hour == 15 and self.Time.minute == 45:
            if self._is_day_before_expiration(self.Time.date(), self.held_expiry):
                self._submit_exit("15:45 pre-expiration time stop")
                return

        contract = self._get_held_contract(data)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self._submit_exit("50% profit target")

    def _get_held_contract(self, data: Slice):
        for chain in data.OptionChains.Values:
            contract = chain.Contracts.get(self.held_option)
            if contract is not None:
                return contract
        return None

    def _is_day_before_expiration(self, current_date, expiry_date):
        next_date = current_date + timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime.combine(next_date, datetime.min.time())
        ):
            next_date += timedelta(days=1)

        return next_date == expiry_date

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0 or self._ticket_is_open(self.exit_ticket):
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order.")

        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug(
            f"{self.Time}: submitted exit for {self.held_option}; reason: {reason}."
        )

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            self.spy_flatten_pending = False
            return

        if self.spy_flatten_pending:
            return

        self.spy_flatten_pending = True
        self.MarketOrder(self.spy, -quantity)
        self.Debug(
            f"{self.Time}: unexpected SPY exercise/assignment position; "
            f"submitted liquidation for {quantity} shares."
        )

    def _ticket_is_open(self, ticket):
        if ticket is None:
            return False

        status = ticket.Status
        return status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted,
            OrderStatus.CancelPending
        ]

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and \
           order_event.OrderId == self.entry_ticket.OrderId:

            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_option = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date.date()
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None

                self.Debug(
                    f"{self.Time}: entry filled for {self.held_option} "
                    f"at {self.entry_price}."
                )

            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_ticket = None
                self.Debug(f"{self.Time}: entry order was not filled.")

        if self.exit_ticket is not None and \
           order_event.OrderId == self.exit_ticket.OrderId:

            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: exit filled for {order_event.Symbol} "
                    f"at {order_event.FillPrice}."
                )
                self.held_option = None
                self.held_expiry = None
                self.entry_price = None
                self.exit_ticket = None

            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

