            self.Debug(f"Skipped entry {self.Time}: no SPY option chain in Slice.")
            return

        contract = self._select_contract(chain)
        if contract is None:
            self.Debug(f"Skipped entry {self.Time}: no qualifying SPY call contract.")
            return

        self._entry_ticket = self.MarketOrder(
            contract.Symbol, 1, False, "5-minute MA bullish crossover entry"
        )
        self.Debug(f"Entry submitted {self.Time}: {contract.Symbol}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self._held_contract = order_event.Symbol
                self._entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled {self.Time}: {order_event.Symbol} "
                    f"at {self._entry_fill_price:.2f}"
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            )
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled {self.Time}: {order_event.Symbol}")

            self._exit_ticket = None

            if (
                self._held_contract is not None
                and self.Portfolio[self._held_contract].Quantity == 0
            ):
                self._held_contract = None
                self._entry_fill_price = 0.0

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        previous_fast = None
        previous_slow = None

        if self._closes.IsReady:
            previous_slow = sum(self._closes[i] for i in range(20)) / 20.0
            previous_fast = sum(self._closes[i] for i in range(5)) / 5.0

        self._closes.Add(float(bar.Close))

        if previous_fast is None or not self._closes.IsReady:
            return

        current_slow = sum(self._closes[i] for i in range(20)) / 20.0
        current_fast = sum(self._closes[i] for i in range(5)) / 5.0

        bar_time = bar.EndTime
        eligible_time = (
            (bar_time.hour == 9 and bar_time.minute >= 45)
            or 10 <= bar_time.hour <= 13
            or (bar_time.hour == 14 and bar_time.minute <= 30)
        )

        if (
            eligible_time
            and previous_fast <= previous_slow
            and current_fast > current_slow
        ):
            self._pending_entry_signal = True

    def _select_contract(self, chain):
        spot = float(self.Securities[self._spy].Price)
        if spot <= 0:
            return None

        today = self.Time.date()
        future_expirations = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Expiry.date() > today
            }
        )

        if not future_expirations:
            return None

        expiration = future_expirations[0]
        minimum_strike = spot * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            return None

        return min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))

    def _process_profit_target(self, slice: Slice):
        if (
            self._held_contract is None
            or self._entry_fill_price <= 0
            or self._exit_order_is_open()
        ):
            return

        quote = slice.QuoteBars.get(self._held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self._entry_fill_price * 1.50:
            self._submit_exit("50% profit target")

    def _process_time_stop(self):
        if self._held_contract is None or self._exit_order_is_open():
            return

        expiration = self._held_contract.ID.Date
        previous_trading_day = self.Securities[
            self._spy
        ].Exchange.Hours.GetPreviousTradingDay(expiration)

        if (
            self.Time.date() == previous_trading_day.date()
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_exit("15:45 pre-expiration time stop")

    def _process_expiration_protection(self):
        if self._held_contract is None:
            return

        expiration_date = self._held_contract.ID.Date.date()
        if self.Time.date() >= expiration_date:
            self._no_entry_date = self.Time.date()

            if not self._exit_order_is_open():
                self.Debug(
                    f"Expiration protection {self.Time}: liquidating "
                    f"{self._held_contract}"
                )
                self._submit_exit("expiration protection")

    def _liquidate_unexpected_spy_position(self):
        if self.Portfolio[self._spy].Invested:
            self.Debug(
                f"Unexpected SPY exercise/assignment position {self.Time}: "
                f"liquidating SPY."
            )
            self.MarketOrder(
                self._spy,
                -self.Portfolio[self._spy].Quantity,
                False,
                "Unexpected exercise/assignment cleanup",
            )

    def _submit_exit(self, reason: str):
        if self._held_contract is None or self._exit_order_is_open():
            return

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity == 0:
            return

        if self._exit_ticket is not None:
            self.Transactions.CancelOrder(self._exit_ticket.OrderId)

        self._exit_ticket = self.MarketOrder(
            self._held_contract, -quantity, False, reason
        )
        self.Debug(f"Exit submitted {self.Time}: {self._held_contract} ({reason})")

    def _has_option_position(self):
        return (
            self._held_contract is not None
            and self.Portfolio[self._held_contract].Quantity != 0
        )

    def _entry_order_is_open(self):
        return self._entry_ticket is not None and self._entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _exit_order_is_open(self):
        return self._exit_ticket is not None and self._exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

