from AlgorithmImports import *
from datetime import datetime, timedelta, time


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    TARGET_DTE = 7

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Securities[self.option_symbol].SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.close_window = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = False
        self.pending_signal_time = None

        self.held_contract = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.equity_flatten_ticket = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.close_window.Add(float(bar.Close))

        if not self.close_window.IsReady:
            return

        closes = [self.close_window[i] for i in range(20)]
        fast = sum(closes[:5]) / 5.0
        slow = sum(closes) / 20.0

        crossed = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = bar.EndTime
        if crossed and time(9, 45) <= bar_end.time() <= time(14, 30):
            self.pending_entry_signal = True
            self.pending_signal_time = bar_end

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing()
        self.HandleExit(slice)

        if (
            self.pending_entry_signal
            and self.pending_signal_time == self.Time
        ):
            self.pending_entry_signal = False
            self.TryEnter(slice)
        elif (
            self.pending_entry_signal
            and self.pending_signal_time is not None
            and self.pending_signal_time < self.Time
        ):
            self.pending_entry_signal = False

    def TryEnter(self, slice):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None:
            holding = self.Portfolio[self.held_contract]
            if holding.Invested:
                return

        if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            return

        if self.Portfolio.Invested:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no SPY option chain in Slice")
            return

        dte_contracts = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - self.Time.date()).days == self.TARGET_DTE
        ]

        if not dte_contracts:
            self.Debug("Skipped entry: no call expiration satisfies DTE rule")
            return

        spot = self.Securities[self.spy].Price
        minimum_strike = spot * 1.01

        eligible = [
            contract
            for contract in dte_contracts
            if float(contract.Strike) >= minimum_strike
        ]

        if not eligible:
            self.Debug("Skipped entry: no call strike at least 1% OTM")
            return

        selected = sorted(
            eligible,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"strike={selected.Strike} expiry={selected.Expiry.date()}"
        )

    def HandleExit(self, slice):
        if self.held_contract is None:
            return

        holding = self.Portfolio[self.held_contract]
        if not holding.Invested:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            return

        expiry = self.held_contract.ID.Date.date()
        prior_trading_day = self.PreviousTradingDay(expiry)

        if (
            self.Time.date() == prior_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("time stop before expiration")
            return

        if self.entry_price is None:
            return

        option_contract = self.FindContract(slice, self.held_contract)
        if option_contract is None:
            return

        bid = float(option_contract.BidPrice)
        ask = float(option_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("50% profit target")

    def HandleExpirationProcessing(self):
        if self.held_contract is None:
            return

        holding = self.Portfolio[self.held_contract]
        if not holding.Invested:
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.no_entry_date = self.Time.date()
            if self.exit_ticket is None or not self.IsOpen(self.exit_ticket):
                self.SubmitExit("expiration processing")

    def HandleUnexpectedEquityPosition(self):
        spy_holding = self.Portfolio[self.spy]
        if not spy_holding.Invested:
            return

        if self.equity_flatten_ticket is None or not self.IsOpen(self.equity_flatten_ticket):
            self.Debug("Unexpected SPY exercise/assignment position detected; flattening")
            self.equity_flatten_ticket = self.MarketOrder(
                self.spy,
                -spy_holding.Quantity
            )

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        holding = self.Portfolio[self.held_contract]
        if not holding.Invested:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            return

        self.exit_ticket = self.MarketOrder(
            self.held_contract,
            -holding.Quantity
        )
        self.Debug(f"Exit submitted: {reason} {self.held_contract}")

    def FindContract(self, slice, symbol):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == symbol:
                return contract

        return None

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime.combine(candidate, time.min)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def IsOpen(self, ticket):
        return ticket is not None and ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.FillQuantity > 0:
                    self.held_contract = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.Debug(
                        f"Entry filled: {order_event.Symbol} "
                        f"price={order_event.FillPrice}"
                    )

            if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} "
                    f"price={order_event.FillPrice}"
                )
                if not self.Portfolio[order_event.Symbol].Invested:
                    self.held_contract = None
                    self.entry_price = None
                    self.exit_ticket = None

            if (
                self.equity_flatten_ticket is not None
                and order_event.OrderId == self.equity_flatten_ticket.OrderId
            ):
                self.equity_flatten_ticket = None

        elif order_event.Status in [
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
                self.entry_ticket = None

            if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
                self.exit_ticket = None

