from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-200, 200, 0, 730)
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_crossover_time = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.held_option = None
        self.held_expiry = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_exit_order_id = None
        self.entry_price = None
        self.no_entry_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.CheckTimeStop
        )

    def OnFiveMinuteBar(self, sender, bar):
        old_fast = self.fast.Current.Value if self.fast.IsReady else None
        old_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if old_fast is None or old_slow is None:
            return

        if old_fast <= old_slow and self.fast.Current.Value > self.slow.Current.Value:
            end_time = bar.EndTime
            if (
                (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
                and (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
            ):
                self.pending_crossover_time = end_time

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpiration()

        if self.pending_crossover_time is not None and self.Time >= self.pending_crossover_time:
            signal_time = self.pending_crossover_time
            self.pending_crossover_time = None
            self.TryEnter(data, signal_time)

        self.CheckProfitTarget(data)

    def TryEnter(self, data, signal_time):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

        if self.IsOrderOpen(self.entry_order_id):
            return

        if self.IsOrderOpen(self.exit_order_id):
            return

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug(f"{signal_time}: skipped entry; no current SPY TradeBar.")
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{signal_time}: skipped entry; no option chain.")
            return

        contracts = list(chain)
        positive_dtes = [
            (contract.Expiry.date() - self.Time.date()).days
            for contract in contracts
            if (contract.Expiry.date() - self.Time.date()).days > 0
        ]

        if not positive_dtes:
            self.Debug(f"{signal_time}: skipped entry; no unexpired option expiration.")
            return

        selected_dte = min(positive_dtes)
        selected_expiry = self.Time.date() + timedelta(days=selected_dte)
        minimum_strike = spy_bar.Close * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{signal_time}: skipped entry; no call at or above "
                f"101% of SPY for {selected_expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_option = selected.Symbol
        self.held_expiry = selected.Expiry.date()
        self.entry_price = None

        self.Debug(
            f"{signal_time}: submitted entry for {selected.Symbol}, "
            f"strike {selected.Strike}, expiry {selected_expiry}."
        )

    def CheckProfitTarget(self, data):
        if self.held_option is None or not self.Portfolio[self.held_option].Invested:
            return

        if self.entry_price is None or self.IsOrderOpen(self.exit_order_id):
            return

        quote = data.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
