from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
                                     .Strikes(-100, 100)
                                     .Expiration(0, 90)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self._averages_ready_before_update = False
        self._pending_five_minute_bar = None

        self.held_contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.no_entry_date = None
        self.spy_flatten_order_id = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

    def OnData(self, data):
        self._handle_unexpected_spy_position()
        self._handle_expiration_day()
        self._evaluate_option_exit(data)

        if self._pending_five_minute_bar is not None:
            bar = self._pending_five_minute_bar
            self._pending_five_minute_bar = None
            self._evaluate_entry(data, bar)

    def _on_five_minute_bar(self, sender, bar):
        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value
        previous_ready = self._averages_ready_before_update

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)
        self._averages_ready_before_update = self.fast.IsReady and self.slow.IsReady

        if (previous_ready and self.fast.IsReady and self.slow.IsReady and
                previous_fast <= previous_slow and
                self.fast.Current.Value > self.slow.Current.Value):
            self._pending_five_minute_bar = bar

    def _evaluate_entry(self, data, bar):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None or self.entry_order_id is not None:
            return

        if self.exit_order_id is not None:
            return

        end_time = bar.EndTime.time()
        if end_time < datetime.time(9, 45) or end_time > datetime.time(14, 30):
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: SPY price unavailable")
            return

        contracts = []
        for chain in data.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Symbol.ID.OptionRight != OptionRight.Call:
                    continue

                expiration = contract.Symbol.ID.Date
                dte = (expiration.date() - self.Time.date()).days
                if dte > 0:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no eligible call expiration")
            return

        selected_expiration = min(contract.Symbol.ID.Date for contract in contracts)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Symbol.ID.Date == selected_expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no call meets strike rule")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(
                f"Entry submitted: {selected.Symbol} "
                f"strike={selected.Strike} expiry={selected.Symbol.ID.Date.date()}"
            )

    def _evaluate_option_exit(self, data):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        if self.exit_order_id is not None:
            return

        expiration = self.held_contract.ID.Date
        if (self.Time.date() == self._previous_trading_day(expiration).date() and
                self.Time.time() == datetime.time(15, 45)):
            self._submit_option_exit("time stop")
            return

        contract = self._find_contract_in_slice(data, self.held_contract)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0 or self.entry_fill_price is None:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_option_exit("profit target")

    def _handle_expiration_day(self):
        if self.held_contract is None:
            return

        if self.Time.date() != self.held_contract.ID.Date.date():
            return

        self.no_entry_date = self.Time.date()
        if self.Portfolio[self.held_contract].Quantity > 0 and self.exit_order_id is None:
            self._submit_option_exit("expiration protection")

    def _submit_option_exit(self, reason):
        if self.exit_order_id is not None or self.held_contract is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        if ticket is not None:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"Exit submitted ({reason}): {self.held_contract}")

    def _find_contract_in_slice(self, data, symbol):
        for chain in data.OptionChains.Values:
            if chain.Contracts.ContainsKey(symbol):
                return chain.Contracts[symbol]
        return None

    def _previous_trading_day(self, expiration):
        date = expiration.AddDays(-1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(date):
            date = date.AddDays(-1)

        return date

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.spy_flatten_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -quantity)
        if ticket is not None:
            self.spy_flatten_order_id = ticket.OrderId
            self.Debug(f"Unexpected SPY exercise/assignment position flattened: {quantity}")

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_fill_price = order_event.FillPrice
                self.held_contract = order_event.Symbol
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} "
                    f"price={self.entry_fill_price:.2f}"
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug("Entry order canceled or invalid")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} "
                    f"price={order_event.FillPrice:.2f}"
                )
                self.exit_order_id = None
                self.held_contract = None
                self.entry_fill_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None
                self.Debug("Exit order canceled or invalid")

        if order_event.OrderId == self.spy_flatten_order_id:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.spy_flatten_order_id = None

