        option.SetFilter(lambda universe: universe.Strikes(-100, 100).Expiration(0, 365))
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.pending_crossover = False
        self.held_contract = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.block_entries_date = None
        self.spy_liquidation_submitted = False

        consolidator = CalendarConsolidator(self.FiveMinuteCalendar)
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def FiveMinuteCalendar(self, time):
        minute = time.minute - (time.minute % 5)
        start = time.replace(minute=minute, second=0, microsecond=0)
        return CalendarInfo(start, timedelta(minutes=5))

    def OnFiveMinuteBar(self, sender, bar):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not previous_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        bar_end = bar.EndTime
        eligible_time = (
            (bar_end.hour == 9 and bar_end.minute >= 45) or
            (10 <= bar_end.hour <= 13) or
            (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        if (eligible_time and
                previous_fast <= previous_slow and
                self.fast.Current.Value > self.slow.Current.Value):
            self.pending_crossover = True

    def OnData(self, data):
        self.HandleUnexpectedSpyHolding()
        self.HandleExpirationProcessing()

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            self.HandleOptionExit(data)

        if self.pending_crossover:
            self.pending_crossover = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.block_entries_date == self.Time.date():
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            return

        if self.HasOpenEntryOrder():
            return

        if not data.OptionChains:
            self.Debug("Entry skipped: no option chain.")
            return

        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug("Entry skipped: invalid SPY price.")
            return

        contracts = []
        for chain in data.OptionChains.values():
            for contract in chain.Contracts:
                if contract.Right == OptionRight.Call and contract.Expiry.date() > self.Time.date():
                    contracts.append(contract)

        if not contracts:
            self.Debug("Entry skipped: no eligible call expiration.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call strike.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1, tag="Crossover call entry")
        self.entry_order_id = ticket.OrderId
        self.held_contract = selected.Symbol
        self.entry_price = None
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def HandleOptionExit(self, data):
        if self.HasOpenExitOrder():
            return

        contract_data = None
        for chain in data.OptionChains.values():
            for contract in chain.Contracts:
                if contract.Symbol == self.held_contract:
                    contract_data = contract
                    break
            if contract_data is not None:
                break

        if contract_data is not None:
            bid = contract_data.BidPrice
            ask = contract_data.AskPrice
            if bid > 0 and ask > 0 and self.entry_price is not None:
                midpoint = (bid + ask) / 2.0
                if midpoint >= self.entry_price * 1.50:
                    self.SubmitOptionExit("Profit target exit")
                    return

        expiry = self.held_contract.ID.Date.date()
        if self.Time.hour == 15 and self.Time.minute == 45:
            next_trading_day = self.Securities[self.spy].Exchange.Hours.GetNextTradingDay(self.Time)
            if next_trading_day.date() == expiry:
                self.SubmitOptionExit("Pre-expiration time stop")

    def HandleExpirationProcessing(self):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        if self.Time.date() >= self.held_contract.ID.Date.date():
            self.block_entries_date = self.Time.date()
            if not self.HasOpenExitOrder():
                self.Debug("Expiration handling: liquidating remaining option.")
                self.SubmitOptionExit("Expiration safety exit")

    def HandleUnexpectedSpyHolding(self):
        if not self.Portfolio[self.spy].Invested:
            self.spy_liquidation_submitted = False
            return

        if not self.spy_liquidation_submitted:
            self.spy_liquidation_submitted = True
            self.Debug("Unexpected SPY exercise/assignment holding: liquidating.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity,
                             tag="Unexpected exercise or assignment liquidation")

    def SubmitOptionExit(self, tag):
        if self.held_contract is None or self.HasOpenExitOrder():
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if order.Id != self.entry_order_id:
                self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity != 0:
            ticket = self.MarketOrder(self.held_contract, -quantity, tag=tag)
            self.exit_order_id = ticket.OrderId
            self.Debug("Exit submitted: {} ({})".format(self.held_contract, tag))

    def HasOpenEntryOrder(self):
        if self.entry_order_id is None:
            return False
        order = self.Transactions.GetOrderById(self.entry_order_id)
        return order is not None and order.Status not in (
            OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
        )

    def HasOpenExitOrder(self):
        if self.exit_order_id is None:
            return False
        order = self.Transactions.GetOrderById(self.exit_order_id)
        return order is not None and order.Status not in (
            OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
        )

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug("Entry filled: {} at {}".format(
                    order_event.Symbol, order_event.FillPrice))
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_order_id = None
                self.held_contract = None
                self.entry_price = None
                self.Debug("Entry canceled or invalid.")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {} at {}".format(
                    order_event.Symbol, order_event.FillPrice))
                self.exit_order_id = None
                self.held_contract = None
                self.entry_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

