from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(-200, 200, 0, 730)

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_crossover = None

        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.closes.append(float(bar.Close))
        self.pending_crossover = None

        if len(self.closes) < 20:
            return

        values = list(self.closes)
        fast = sum(values[-5:]) / 5.0
        slow = sum(values) / 20.0

        if self.previous_fast is not None:
            end_time = bar.EndTime
            eligible_time = (
                (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
                and
                (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
            )

            if eligible_time and self.previous_fast <= self.previous_slow and fast > slow:
                self.pending_crossover = bar.EndTime

        self.previous_fast = fast
        self.previous_slow = slow

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing()
        self.HandleExits(data)

        if self.pending_crossover is not None:
            crossover_time = self.pending_crossover
            self.pending_crossover = None
            self.TryEnter(data, crossover_time)

    def TryEnter(self, data, crossover_time):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self.HasOpenEntryOrder():
            return

        chain = data.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug(f"{crossover_time}: skipped entry; no option chain")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug(f"{crossover_time}: skipped entry; invalid SPY price")
            return

        today = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() > today
        })

        if not expirations:
            self.Debug(f"{crossover_time}: skipped entry; no valid future call expiration")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{crossover_time}: skipped entry; no call at or above 101% SPY "
                f"for {selected_expiry}"
            )
            return

        contract = min(candidates, key=lambda x: (x.Strike, str(x.Symbol)))
        self.held_symbol = contract.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)

        self.Debug(
            f"{crossover_time}: entering 1 {contract.Symbol} "
            f"strike={contract.Strike} expiry={contract.Expiry.date()}"
        )

    def HandleExits(self, data):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0 or self.entry_price is None or self.HasOpenExitOrder():
            return

        quote = data.QuoteBars.get(self.held_symbol)
        if quote is not None and quote.Bid is not None and quote.Ask is not None:
            bid = quote.Bid.Close
            ask = quote.Ask.Close

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= self.entry_price * 1.50:
                    self.SubmitExit(
                        f"profit target reached; midpoint={midpoint:.2f}, "
                        f"entry={self.entry_price:.2f}"
                    )
                    return

        expiry = self.held_symbol.ID.Date.date()
        if self.Time.hour == 15 and self.Time.minute == 45:
            prior_trading_day = self.PreviousSpyTradingDay(expiry)
            if self.Time.date() == prior_trading_day:
                self.SubmitExit(f"15:45 pre-expiration exit for {expiry}")

    def HandleExpirationProcessing(self):
        if self.held_symbol is None:
            return

        expiry = self.held_symbol.ID.Date.date()
        if self.Time.date() >= expiry:
            self.no_entry_date = self.Time.date()

            if self.Portfolio[self.held_symbol].Quantity > 0 and not self.HasOpenExitOrder():
                self.SubmitExit(f"expiration processing exit for {expiry}")

    def HandleUnexpectedSpyPosition(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"unexpected SPY position ({spy_quantity}) from exercise/assignment; liquidating"
            )
            self.MarketOrder(self.spy, -spy_quantity)

    def PreviousSpyTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing prior exit order")

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug(f"{self.Time}: exiting {self.held_symbol}; {reason}")

    def OnOrderEvent(self, orderEvent):
        if self.entry_ticket is not None and orderEvent.OrderId == self.entry_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled and orderEvent.FillQuantity > 0:
                self.entry_price = orderEvent.FillPrice
                self.Debug(
                    f"{self.Time}: entry filled {self.held_symbol} at {self.entry_price:.2f}"
                )

            if orderEvent.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"{self.Time}: entry order {orderEvent.Status}")
                self.held_symbol = None
                self.entry_price = None

        if self.exit_ticket is not None and orderEvent.OrderId == self.exit_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: exit filled {orderEvent.Symbol} at {orderEvent.FillPrice:.2f}"
                )
                self.held_symbol = None
                self.entry_price = None
                self.entry_ticket = None
                self.exit_ticket = None

    def HasOpenEntryOrder(self):
        return self.entry_ticket is not None and self.IsOpen(self.entry_ticket)

    def HasOpenExitOrder(self):
        return self.exit_ticket is not None and self.IsOpen(self.exit_ticket)

    def IsOpen(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )
